1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.util.DisposableEmailDomains;
12	import org.springframework.samples.petclinic.util.E164PhoneNumbers;
13	import org.springframework.samples.petclinic.util.IdentityKeyUtils;
14	
15	import java.time.LocalDate;
16	import java.time.Month;
17	import java.time.Period;
18	import java.util.Collection;
19	import java.util.List;
20	import java.util.Map;
21	
22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public interface OwnerMapper {
27	
28	    @Mapping(target = "displayName",
29	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
30	    @Mapping(target = "initials",
31	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
32	            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
33	    @Mapping(target = "membershipPoints",
34	        expression = "java(toMembershipPoints(owner))")
35	    @Mapping(target = "membershipLevel",
36	        expression = "java(toMembershipLevel(owner))")
37	    @Mapping(target = "locality",
38	        expression = "java(toLocality(owner))")
39	    @Mapping(target = "ownerSegment",
40	        expression = "java(toOwnerSegment(owner))")
41	    @Mapping(target = "timezone",
42	        expression = "java(toTimezone(owner))")
43	    @Mapping(target = "contactPreference",
44	        expression = "java(toContactPreference(owner))")
45	    @Mapping(target = "identityKey",
46	        expression = "java(toIdentityKey(owner))")
47	    @Mapping(target = "ageBand",
48	        expression = "java(toAgeBand(owner))")
49	    @Mapping(target = "telephoneDisplay",
50	        expression = "java(toTelephoneDisplay(owner))")
51	    @Mapping(target = "salutation",
52	        expression = "java(toSalutation(owner))")
53	    @Mapping(target = "fiscalYear",
54	        expression = "java(toFiscalYear(owner))")
55	    @Mapping(target = "selfLink",
56	        expression = "java(toSelfLink(owner))")
57	    @Mapping(target = "riskFlag",
58	        expression = "java(toRiskFlag(owner))")
59	    OwnerDto toOwnerDto(Owner owner);
60	
61	    /**
62	     * Derive an owner's risk flag: {@code true} when the owner warrants a manual risk review, defined
63	     * as the logical OR of three conditions — the owner is a possible duplicate
64	     * ({@code possibleDuplicate} is true), the owner's email domain is disposable-adjacent (see
65	     * {@link #hasDisposableAdjacentEmail(Owner)}), or the owner's city is over its soft capacity
66	     * ({@code capacityWarning} is true). Otherwise {@code false}. Derived at read time.
67	     */
68	    default Boolean toRiskFlag(Owner owner) {
69	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
70	            || Boolean.TRUE.equals(owner.getCapacityWarning())
71	            || hasDisposableAdjacentEmail(owner);
72	    }
73	
74	    /**
75	     * Whether the owner's email domain is disposable-adjacent: a domain that is not itself a
76	     * whole-blocklisted disposable domain (those are rejected at creation) but shares a known
77	     * disposable provider's second-level label — i.e. one of the domain's dot-separated labels equals a
78	     * label in {@link DisposableEmailDomains#BASE_LABELS}. This catches subdomains of a disposable provider
79	     * (e.g. {@code sub.mailinator.com}) and the same base under a different TLD (e.g.
80	     * {@code mailinator.net}), while a merely similar label (e.g. {@code mymailinator.com}) is not
81	     * matched. Returns {@code false} when the owner has no email or the value carries no domain.
82	     */
83	    default boolean hasDisposableAdjacentEmail(Owner owner) {
84	        if (!hasEmail(owner)) {
85	            return false;
86	        }
87	        String email = owner.getEmail();
88	        int at = email.lastIndexOf('@');
89	        if (at < 0 || at == email.length() - 1) {
90	            return false;
91	        }
92	        String domain = email.substring(at + 1).toLowerCase();
93	        for (String label : domain.split("\\.")) {
94	            if (DisposableEmailDomains.BASE_LABELS.contains(label)) {
95	                return true;
96	            }
97	        }
98	        return false;
99	    }
100	
101	    /**
102	     * Derive an owner's canonical self link: the resource path {@code '/api/owners/<id>'} where
103	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet (the field is
104	     * then absent from the DTO).
105	     */
106	    default String toSelfLink(Owner owner) {
107	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
108	    }
109	
110	    /**
111	     * The fiscal year that the given date falls in, where the fiscal year starts on 1 July and is
112	     * identified by the calendar year in which it ends. A date on or after 1 July belongs to the
113	     * fiscal year ending in the following calendar year (e.g. 2026-08-01 -&gt; 2027), while a date
114	     * before 1 July belongs to the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt;
115	     * 2026). This is the single source of truth for the fiscal year used both when the create endpoint
116	     * bakes the FY segment into the member id (see {@code OwnerRestControllerV1.memberIdFor}) and when
117	     * the DTO's {@code fiscalYear} falls back to the registration date for a legacy record.
118	     *
119	     * @param date the date to resolve, on a business day
120	     * @return the calendar year in which that date's fiscal year ends
121	     */
122	    static int fiscalYear(LocalDate date) {
123	        int year = date.getYear();
124	        return date.getMonthValue() >= Month.JULY.getValue() ? year + 1 : year;
125	    }
126	
127	    /**
128	     * Derive an owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the two-digit fiscal-year
129	     * segment carried by the {@code memberId} (see {@link #memberIdBase(String)}), e.g. {@code 'FY27'}.
130	     * The fiscal year therefore moves with the owner's member id. When an owner has no (well-formed)
131	     * member id yet (e.g. legacy records) it falls back to deriving the fiscal year directly from the
132	     * business-day-adjusted {@code registrationDate} (see {@link #fiscalYear(LocalDate)}), and returns
133	     * {@code null} when neither is present (the field is then absent from the DTO).
134	     */
135	    default String toFiscalYear(Owner owner) {
136	        String base = memberIdBase(owner.getMemberId());
137	        if (base != null) {
138	            return "FY" + memberIdFyDigits(base);
139	        }
140	        LocalDate registrationDate = owner.getRegistrationDate();
141	        return registrationDate == null ? null : String.format("FY%02d", fiscalYear(registrationDate) % 100);
142	    }
143	
144	    /**
145	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
146	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
147	     * just the last name.
148	     */
149	    default String toSalutation(Owner owner) {
150	        String lastName = owner.getLastName();
151	        String title = owner.getTitle();
152	        if (title == null || title.isBlank()) {
153	            return lastName;
154	        }
155	        return title + " " + lastName;
156	    }
157	
158	    /**
159	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
160	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
161	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
162	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
163	     */
164	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
165	        LocalDate birthDate = owner.getBirthDate();
166	        if (birthDate == null) {
167	            return null;
168	        }
169	        LocalDate reference = owner.getRegistrationDate() != null
170	            ? owner.getRegistrationDate() : LocalDate.now();
171	        int age = Period.between(birthDate, reference).getYears();
172	        if (age < 18) {
173	            return OwnerDto.AgeBandEnum.MINOR;
174	        }
175	        if (age < 65) {
176	            return OwnerDto.AgeBandEnum.ADULT;
177	        }
178	        return OwnerDto.AgeBandEnum.SENIOR;
179	    }
180	
181	    /**
182	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
183	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
184	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
185	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
186	     *
187	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
188	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
189	     * code, a two-digit country code is assumed (the most common length).
190	     */
191	    default String toTelephoneDisplay(Owner owner) {
192	        String telephone = owner.getTelephone();
193	        if (telephone == null || !telephone.startsWith("+")) {
194	            return telephone;
195	        }
196	        String digits = telephone.substring(1);
197	        String code = E164PhoneNumbers.countryCode(digits)
198	            .filter(c -> digits.length() > c.length())
199	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
200	        String national = digits.substring(code.length());
201	        StringBuilder sb = new StringBuilder("+").append(code);
202	        for (int i = 0; i < national.length(); i += 3) {
203	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
204	        }
205	        return sb.toString();
206	    }
207	
208	    /**
209	     * The fixed trailing-segment widths of a member id base {@code '<REGION><FY><HASH8><CHK>'}: FY is 2
210	     * digits, HASH8 is 8 hex characters and CHK is 1 digit, so the last {@link #MEMBER_ID_SUFFIX_WIDTH}
211	     * characters are the {@code <FY><HASH8><CHK>} suffix and REGION is the variable-width remainder in
212	     * front of it. This is the single place the layout is encoded; the position arithmetic in
213	     * {@link #memberIdRegion(String)} and {@link #memberIdFyDigits(String)} derives from these, and it
214	     * must stay in step with how {@code OwnerRestControllerV1.memberIdFor} assembles the id.
215	     */
216	    int FY_WIDTH = 2;
217	    int HASH8_WIDTH = 8;
218	    int CHK_WIDTH = 1;
219	    int MEMBER_ID_SUFFIX_WIDTH = FY_WIDTH + HASH8_WIDTH + CHK_WIDTH;
220	
221	    /**
222	     * The {@code '<REGION><FY><HASH8><CHK>'} base of a member id, dropping any {@code '-<n>'} collision
223	     * suffix, or {@code null} when the owner has no (well-formed) member id yet — i.e. one long enough to
224	     * carry a non-empty REGION in front of the fixed {@link #MEMBER_ID_SUFFIX_WIDTH}-character suffix.
225	     * Use {@link #memberIdRegion(String)} and {@link #memberIdFyDigits(String)} to decode its segments.
226	     */
227	    private static String memberIdBase(String memberId) {
228	        if (memberId == null) {
229	            return null;
230	        }
231	        int dash = memberId.indexOf('-');
232	        String base = dash >= 0 ? memberId.substring(0, dash) : memberId;
233	        return base.length() > MEMBER_ID_SUFFIX_WIDTH ? base : null;
234	    }
235	
236	    /**
237	     * The leading {@code <REGION>} segment of a (non-null, well-formed) member id base: everything
238	     * before the fixed trailing {@code <FY><HASH8><CHK>} suffix.
239	     */
240	    private static String memberIdRegion(String base) {
241	        return base.substring(0, base.length() - MEMBER_ID_SUFFIX_WIDTH);
242	    }
243	
244	    /**
245	     * The two-digit {@code <FY>} segment of a (non-null, well-formed) member id base: the characters
246	     * immediately preceding the trailing HASH8 and CHK segments.
247	     */
248	    private static String memberIdFyDigits(String base) {
249	        int fyEnd = base.length() - HASH8_WIDTH - CHK_WIDTH;
250	        return base.substring(fyEnd - FY_WIDTH, fyEnd);
251	    }
252	
253	    /**
254	     * Derive an owner's duplicate-detection identity key: the lower-case SHA-256 hex digest (64
255	     * characters) of the normalized E.164 telephone, the lower-cased email (empty when none) and the
256	     * American Soundex code of the last name, joined with {@code '|'}. Two owners are duplicates only
257	     * when their whole identity keys are equal.
258	     *
259	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
260	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
261	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}, and the Soundex and
262	     * hashing come from {@link IdentityKeyUtils}, the same helpers the soft-match uses.
263	     */
264	    default String toIdentityKey(Owner owner) {
265	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
266	        String email = hasEmail(owner) ? owner.getEmail() : "";
267	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
268	        return IdentityKeyUtils.sha256Hex(telephone + "|" + email + "|" + soundex);
269	    }
270	
271	    /**
272	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
273	     * for the "is an email present" rule shared by the derived fields below.
274	     */
275	    default boolean hasEmail(Owner owner) {
276	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
277	    }
278	
279	    /**
280	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
281	     * otherwise 'PHONE'.
282	     */
283	    default String toContactPreference(Owner owner) {
284	        return hasEmail(owner) ? "EMAIL" : "PHONE";
285	    }
286	
287	    /**
288	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
289	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
290	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
291	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
292	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
293	     * and no namesakes in a single-member household scores 3 points.
294	     */
295	    default Integer toMembershipPoints(Owner owner) {
296	        int points = 0;
297	        if (hasEmail(owner)) {
298	            points += 2;
299	        }
300	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
301	        if (noNamesakes) {
302	            points += 1;
303	        }
304	        if (hasHouseholdBonus(owner)) {
305	            points += 2;
306	        }
307	        if (hasTenureBonus(owner)) {
308	            points += 3;
309	        }
310	        return points;
311	    }
312	
313	    /**
314	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
315	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
316	     * Returns {@code false} when no household size is present (e.g. legacy records).
317	     */
318	    default boolean hasHouseholdBonus(Owner owner) {
319	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
320	    }
321	
322	    /**
323	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
324	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
325	     * or more.
326	     *
327	     * <p>The level is then capped at the owner's {@code membershipLevelCap} when one is present: a new
328	     * owner's membership level cannot exceed one above the current maximum membership level among their
329	     * existing household members, so the cap (frozen at creation, see the create endpoint) is the
330	     * ceiling applied here. When no cap is present (e.g. an owner created with no existing household
331	     * member, or a legacy record) the uncapped level stands.
332	     */
333	    default Integer toMembershipLevel(Owner owner) {
334	        int level = uncappedMembershipLevel(owner);
335	        Integer cap = owner.getMembershipLevelCap();
336	        if (cap != null && level > cap) {
337	            return cap;
338	        }
339	        return level;
340	    }
341	
342	    /**
343	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
344	     * {@link #toMembershipPoints(Owner)}) before any household ceiling is applied: level 1 for 0-1
345	     * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
346	     */
347	    default Integer uncappedMembershipLevel(Owner owner) {
348	        int points = toMembershipPoints(owner);
349	        if (points <= 1) {
350	            return 1;
351	        }
352	        if (points <= 3) {
353	            return 2;
354	        }
355	        if (points <= 5) {
356	            return 3;
357	        }
358	        return 4;
359	    }
360	
361	    /**
362	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
363	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
364	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
365	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
366	     * no registration date is present.
367	     */
368	    default boolean hasTenureBonus(Owner owner) {
369	        LocalDate registrationDate = owner.getRegistrationDate();
370	        if (registrationDate == null) {
371	            return false;
372	        }
373	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
374	    }
375	
376	    /**
377	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
378	     */
379	    Map<String, String> CITY_REGION = Map.of(
380	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
381	
382	    /**
383	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
384	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
385	     * inclusive.
386	     */
387	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
388	        "NSW", new int[] {2000, 2099},
389	        "VIC", new int[] {3000, 3099},
390	        "QLD", new int[] {4000, 4099});
391	
392	    /**
393	     * Derive an owner's locality (region) from the region-and-hash member id: the leading
394	     * {@code <REGION>} segment of the {@code memberId}, i.e. everything before its trailing FY, HASH8
395	     * and CHK segments (see {@link #memberIdBase(String)}). Since the region is baked into the member id
396	     * at creation (see the create endpoint), the locality now moves with that identity rather than being
397	     * recomputed from the postcode and city. When an owner has no (well-formed) member id yet (e.g.
398	     * legacy records), fall back to deriving the region directly via {@link #regionOf(Owner)}.
399	     */
400	    default String toLocality(Owner owner) {
401	        String base = memberIdBase(owner.getMemberId());
402	        if (base != null) {
403	            return memberIdRegion(base);
404	        }
405	        return regionOf(owner);
406	    }
407	
408	    /**
409	     * Derive an owner's marketing segment, formatted {@code '<TIER>_<AREA>'} and one of
410	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
411	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when the owner's membership level (see
412	     * {@link #toMembershipLevel(Owner)}) is 3 or more, otherwise {@code 'STANDARD'}. AREA is
413	     * {@code 'METRO'} when the owner's locality (see {@link #toLocality(Owner)}) is a known region
414	     * (NSW, VIC or QLD, i.e. one carrying a {@link #REGION_TIMEZONE} entry), otherwise
415	     * {@code 'REGIONAL'}.
416	     */
417	    default String toOwnerSegment(Owner owner) {
418	        String tier = toMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
419	        String area = REGION_TIMEZONE.containsKey(toLocality(owner)) ? "METRO" : "REGIONAL";
420	        return tier + "_" + area;
421	    }
422	
423	    /**
424	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
425	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
426	     */
427	    Map<String, String> REGION_TIMEZONE = Map.of(
428	        "NSW", "Australia/Sydney",
429	        "VIC", "Australia/Melbourne",
430	        "QLD", "Australia/Brisbane");
431	
432	    /**
433	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
434	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
435	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
436	     */
437	    default String toTimezone(Owner owner) {
438	        return REGION_TIMEZONE.get(toLocality(owner));
439	    }
440	
441	    /**
442	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
443	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
444	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
445	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
446	     * the leading {@code <REGION>} segment of a new owner's member id and, through it, the owner's
447	     * locality.
448	     */
449	    default String regionOf(Owner owner) {
450	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
451	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
452	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
453	        String postcode = owner.getPostcode();
454	        if (postcode != null) {
455	            try {
456	                int value = Integer.parseInt(postcode.trim());
457	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
458	                    int[] range = entry.getValue();
459	                    if (value >= range[0] && value <= range[1]) {
460	                        return entry.getKey();
461	                    }
462	                }
463	            }
464	            catch (NumberFormatException ignored) {
465	                // Non-numeric postcode: fall back to the city table below.
466	            }
467	        }
468	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
469	    }
470	
471	    Owner toOwner(OwnerDto ownerDto);
472	
473	    @Mapping(target = "id", ignore = true)
474	    @Mapping(target = "pets", ignore = true)
475	    Owner toOwner(OwnerFieldsDto ownerDto);
476	
477	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
478	
479	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
480	
481	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
482	        OwnerPageDto ownerPageDto = new OwnerPageDto();
483	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
484	        ownerPageDto.setPage(ownerPage.getNumber());
485	        ownerPageDto.setSize(ownerPage.getSize());
486	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
487	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
488	        return ownerPageDto;
489	    }
490	}
