312	
313	    /**
314	     * The owner's current primary identifier, carried by the structured {@link OwnerCreatedEvent}.
315	     * An owner's primary identifier is its {@code memberId}; this single accessor is the one place that
316	     * decides which field is primary, so the audit event always carries the member id.
317	     *
318	     * @param owner the created owner
319	     * @return the owner's current primary identifier
320	     */
321	    private String primaryIdentifier(Owner owner) {
322	        return owner.getMemberId();
323	    }
324	
325	    /**
326	     * Builds the member id for a new owner, formatted {@code '<REGION><FY><HASH8><CHK>'} where REGION is
327	     * the region derived from the owner's postcode (preferring the postcode, falling back to the city
328	     * table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}), FY is the two-digit fiscal
329	     * year (starting 1 July; see {@link OwnerMapper#fiscalYear(LocalDate)}) of the business-day-adjusted
330	     * registration date, HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of the
331	     * owner's normalized E.164 telephone concatenated with the last name, and CHK is a single Luhn check
332	     * digit computed over the digits of {@code '<REGION><FY><HASH8>'} (see
333	     * {@link IdentityKeyUtils#luhnCheckDigit(String)}), e.g. {@code 'NSW271A2B3C4D5'}. The id carries no
334	     * sequence number, so its base form is a stable function of the owner's region, fiscal year and
335	     * telephone/last-name identity rather than of creation order.
336	     *
337	     * <p>When that computed id already belongs to an existing owner it is de-duplicated by appending
338	     * {@code '-<n>'} with the smallest {@code n} of 2 or more that yields an id no existing owner
339	     * already has; the de-duplicated id is returned.
340	     *
341	     * @param owner the owner being created, with its telephone already normalized to E.164 form and its
342	     *              registration date already business-day-adjusted
343	     * @return the assigned, collision-free member id
344	     */
345	    private String memberIdFor(Owner owner) {
346	        String region = ownerMapper.regionOf(owner);
347	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
348	        String hash8 = IdentityKeyUtils.sha256UpperHex(owner.getTelephone() + owner.getLastName())
349	            .substring(0, 8);
350	        String base = region + fy + hash8;
351	        String memberId = base + IdentityKeyUtils.luhnCheckDigit(base);
352	        if (!isMemberIdInUse(memberId)) {
353	            return memberId;
354	        }
355	        int n = 2;
356	        String candidate = memberId + "-" + n;
357	        while (isMemberIdInUse(candidate)) {
358	            n++;
359	            candidate = memberId + "-" + n;
360	        }
361	        return candidate;
362	    }
363	
364	    /**
365	     * Determines whether any existing owner already carries the given {@code memberId}, compared
366	     * exactly. Called while assigning a new owner's member id so collisions can be de-duplicated.
367	     *
368	     * @param memberId the candidate member id to look for
369	     * @return {@code true} if an existing owner already has that member id
370	     */
371	    private boolean isMemberIdInUse(String memberId) {
372	        for (Owner existing : this.clinicService.findAllOwners()) {
373	            if (memberId.equals(existing.getMemberId())) {
374	                return true;
375	            }
376	        }
377	        return false;
378	    }
379	
380	    /**
381	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
382	     * owner's city already contains this many owners.
383	     */
384	    private static final int CITY_CAPACITY = 50;
385	
386	    /**
387	     * The number of owners a city must already contain before a new owner in it is flagged with
388	     * {@code capacityWarning}. Once the city holds this many owners (but fewer than
389	     * {@link #CITY_CAPACITY}), the create still succeeds but is flagged as approaching the capacity
390	     * limit.
391	     */
392	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
393	
394	    /**
395	     * The maximum number of owners that may be created on a single day. A create is rejected with
396	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
397	     * {@code registrationDate}.
398	     */
399	    private static final int DAILY_CREATE_LIMIT = 100;
400	
401	    /**
402	     * The number of owners that must already have been created for the current day before a new
403	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
404	     * owners already carry today's {@code registrationDate}.
405	     */
406	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
407	
408	    /**
409	     * The fixed public holidays that the business-day roll skips. A registration date landing on one
410	     * of these dates is rolled forward, exactly as it is for a weekend day.
411	     */
412	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
413	        LocalDate.parse("2026-01-01"),
414	        LocalDate.parse("2026-01-26"),
415	        LocalDate.parse("2026-04-25"),
416	        LocalDate.parse("2026-12-25"),
417	        LocalDate.parse("2026-12-28"));
418	
419	    /**
420	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
421	     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
422	     * that is not a public holiday, while a date already on a non-holiday weekday is returned
423	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
424	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
425	     * falls on a business day.
426	     *
427	     * @param date the effective registration date
428	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
429	     */
430	    private static LocalDate rollToBusinessDay(LocalDate date) {
431	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
432	            date = date.plusDays(1);
433	        }
434	        return date;
435	    }
436	
437	    private static boolean isWeekend(LocalDate date) {
438	        return switch (date.getDayOfWeek()) {
439	            case SATURDAY, SUNDAY -> true;
440	            default -> false;
441	        };
442	    }
443	
444	    /**
445	     * Counts the existing owners whose {@code registrationDate} equals the given (already
446	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
447	     * business day. Called before a new owner is saved, so the returned value reflects the number of
448	     * owners created for that day prior to this create.
449	     *
450	     * @param date the adjusted business-day registration date to count against
451	     * @return the number of existing owners registered on that date
452	     */
453	    private int countOwnersRegisteredOn(LocalDate date) {
454	        return (int) this.clinicService.findAllOwners().stream()
455	            .filter(existing -> date.equals(existing.getRegistrationDate()))
456	            .count();
457	    }
458	
459	    /**
460	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
461	     *
462	     * @param city the city to count owners for
463	     * @return the number of existing owners in that city
464	     */
465	    private int countOwnersInCity(String city) {
466	        return (int) this.clinicService.findAllOwners().stream()
467	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
468	            .count();
469	    }
470	
471	    /**
472	     * Counts the existing owners that already share the given first name and last name, comparing
473	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
474	     * the number of namesakes that existed prior to this create.
475	     *
476	     * @param firstName the new owner's first name
477	     * @param lastName  the new owner's last name
478	     * @return the number of existing owners with the same first and last name
479	     */
480	    private int countNamesakes(String firstName, String lastName) {
481	        int count = 0;
482	        for (Owner existing : this.clinicService.findAllOwners()) {
483	            if (firstName.equalsIgnoreCase(existing.getFirstName())
484	                && lastName.equalsIgnoreCase(existing.getLastName())) {
485	                count++;
486	            }
487	        }
488	        return count;
489	    }
490	
491	    /**
492	     * Counts the existing owners that already belong to the given household (i.e. that share the
493	     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
494	     * being created yields the household's total size at the moment of creation. Owners without a
495	     * household id are ignored.
496	     *
497	     * @param householdId the new owner's assigned household id
498	     * @return the number of existing owners already in that household
499	     */
500	    private int countHouseholdMembers(String householdId) {
501	        if (householdId == null) {
502	            return 0;
503	        }
504	        int count = 0;
505	        for (Owner existing : this.clinicService.findAllOwners()) {
506	            if (householdId.equals(existing.getHouseholdId())) {
507	                count++;
508	            }
509	        }
510	        return count;
511	    }
512	
513	    /**
514	     * Computes the membership-level ceiling for a new owner joining the given household: one above the
515	     * current maximum effective membership level among the existing owners in that household. The
516	     * ceiling is frozen on the owner at creation and later applied by
517	     * {@link OwnerMapper#toMembershipLevel(Owner)}. Returns {@code null} when the household has no
518	     * existing member (or the owner has no household id), meaning no cap applies.
519	     *
520	     * @param householdId the new owner's assigned household id
521	     * @return one above the household's current maximum membership level, or {@code null} when the
522	     *         household has no existing member
523	     */
524	    private Integer householdMembershipLevelCap(String householdId) {
525	        if (householdId == null) {
526	            return null;
527	        }
528	        Integer maxLevel = null;
529	        for (Owner existing : this.clinicService.findAllOwners()) {
530	            if (householdId.equals(existing.getHouseholdId())) {
531	                int level = ownerMapper.toMembershipLevel(existing);
532	                if (maxLevel == null || level > maxLevel) {
533	                    maxLevel = level;
534	                }
535	            }
536	        }
537	        return maxLevel == null ? null : maxLevel + 1;
538	    }
539	
540	    /**
541	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
542	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
543	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
544	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
545	     * string is what gets stored and returned.
546	     *
547	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
548	     *
549	     * <p>Once in E.164 form the national-number length is validated against the country code: a
550	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
551	     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
552	     * rule are accepted on the general 8-to-15 digit length alone.
553	     *
554	     * @param telephone the raw telephone value supplied by the client
555	     * @return the normalized E.164 telephone number
556	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
557	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
558	     *                                 after the {@code '+'}, or the wrong national-number length for
559	     *                                 its country code)
560	     */
561	    private static String normalizeTelephone(String telephone) {
562	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
563	        String digits;
564	        if (cleaned.startsWith("+")) {
565	            digits = cleaned.substring(1);
566	        } else {
567	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
568	            digits = "61" + national;
569	        }
570	        if (!digits.matches("[0-9]{8,15}")) {
571	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
572	                "telephone could not be normalized to a valid E.164 number");
573	        }
574	        validateNationalNumberLength(digits);
575	        return "+" + digits;
576	    }
577	
578	    /**
579	     * Validates the national-number length of an E.164 number (its digits, without the leading
580	     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
581	     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
582	     * (only the general 8-to-15 digit rule applies).
583	     *
584	     * @param digits the E.164 digits without the leading {@code '+'}
585	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
586	     *                                 digits does not match the country code's required length
587	     */
588	    private static void validateNationalNumberLength(String digits) {
589	        E164PhoneNumbers.countryCode(digits)
590	            .ifPresent(code -> {
591	                int nationalLength = digits.length() - code.length();
592	                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
593	                if (nationalLength != required) {
594	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
595	                        "telephone must have " + required
596	                            + " national digits for country code +" + code);
597	                }
598	            });
599	    }
600	
601	    /**
602	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
603	     * containing at least one dot, none of the three sections containing whitespace or an
604	     * additional {@code @}.
605	     */
606	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
607	
608	    /**
609	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
610	     * (email is optional). When a value is supplied it must be a syntactically valid address whose
611	     * domain is not on the disposable-domain blocklist; the value is then stored and returned
612	     * lower-cased.
613	     *
614	     * @param email the raw email value supplied by the client, possibly {@code null}
615	     * @return the lower-cased email, or {@code null} when none was supplied
616	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
617	     *                                 is not a syntactically valid address, or its domain is on the
618	     *                                 disposable-domain blocklist
619	     */
620	    private static String normalizeEmail(String email) {
621	        if (email == null) {
622	            return null;
623	        }
624	        if (!EMAIL_PATTERN.matcher(email).matches()) {
625	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
626	                "email must be a syntactically valid address");
627	        }
628	        String normalized = email.toLowerCase(Locale.ROOT);
629	        String domain = normalized.substring(normalized.indexOf('@') + 1);
630	        if (DisposableEmailDomains.BLOCKLIST.contains(domain)) {
631	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
632	                "email domain " + domain + " is not allowed");
633	        }
634	        return normalized;
635	    }
636	
637	    /**
638	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
639	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
640	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
641	     */
642	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
643	        "NSW", new int[] {2000, 2099},
644	        "VIC", new int[] {3000, 3099},
645	        "QLD", new int[] {4000, 4099});
646	
647	    /**
648	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
649	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
650	     * four-digit format is enforced by request validation; here the value is range-checked: when the
651	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
652	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
653	     * accepts any four-digit postcode.
654	     *
655	     * @param city     the owner's city
656	     * @param postcode the owner's postcode, possibly {@code null}
657	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
658	     *                                 out of range for the city's region
659	     */
660	    private static void validatePostcode(String city, String postcode) {
661	        if (postcode == null) {
662	            return;
663	        }
664	        String region = OwnerMapper.CITY_REGION.get(city);
665	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
666	        if (range == null) {
667	            return;
668	        }
669	        int value = Integer.parseInt(postcode);
670	        if (value < range[0] || value > range[1]) {
671	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
672	                "postcode " + postcode + " is not valid for region " + region);
673	        }
674	    }
675	
676	    /**
677	     * Common street-type abbreviations expanded to their full word during address normalization.
678	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
679	     */
680	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
681	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
682	
683	    /**
684	     * Applies an owner's address, accepting either the structured form (a non-blank
685	     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
686	     * preferring the structured fields when present. Whichever fields are supplied are normalized
687	     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
688	     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
689	     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
690	     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
691	     * This keeps the request contract backward-compatible: an owner that supplied just the flat
692	     * {@code address} (plus city) is still accepted.
693	     *
694	     * @param owner the owner being created or updated, carrying the raw address fields
695	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
696	     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
697	     *                                 supplied
698	     */
699	    private static void applyAddress(Owner owner) {
700	        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
701	        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
702	        if (!hasStructured && !hasFlat) {
703	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
704	                "an address must be supplied, either 'addressLine1' or 'address'");
705	        }
706	        if (hasStructured) {
707	            String line1 = normalizeAddress(owner.getAddressLine1());
708	            owner.setAddressLine1(line1);
709	            String composed = line1;
710	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
711	                String line2 = normalizeAddress(owner.getAddressLine2());
712	                owner.setAddressLine2(line2);
713	                composed = line1 + " " + line2;
714	            } else {
715	                owner.setAddressLine2(null);
716	            }
717	            owner.setAddress(composed);
718	        } else {
719	            owner.setAddressLine1(null);
720	            owner.setAddressLine2(null);
721	            owner.setAddress(normalizeAddress(owner.getAddress()));
722	        }
723	    }
724	
725	    /**
726	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
727	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
728	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
729	     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
730	     *
731	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
732	     *
733	     * @param address the raw address supplied by the client, possibly {@code null}
734	     * @return the normalized address
735	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
736	     *                                 after normalization (required field)
737	     */
738	    private static String normalizeAddress(String address) {
739	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
740	        if (collapsed.isEmpty()) {
741	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
742	                "address must not be blank");
743	        }
744	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
745	        StringBuilder normalized = new StringBuilder();
746	        for (int i = 0; i < tokens.length; i++) {
747	            if (i > 0) {
748	                normalized.append(' ');
749	            }
750	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
751	        }
752	        return normalized.toString();
753	    }
754	
755	    /**
756	     * Determines whether the given whole identity key already belongs to any owner other than the
757	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
758	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
759	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
760	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
761	     *
762	     * @param identityKey the identity key to look for
763	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
764	     * @return {@code true} if another owner already has the same identity key
765	     */
766	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
767	        for (Owner existing : this.clinicService.findAllOwners()) {
768	            if (existing.isDeleted()) {
769	                continue;
770	            }
771	            if (excludeId != null && excludeId.equals(existing.getId())) {
772	                continue;
773	            }
774	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
775	                return true;
776	            }
777	        }
778	        return false;
779	    }
780	
781	    /**
782	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
783	     * (soft) duplicate of: one whose identity key <em>differs</em> from the new owner's while sharing
784	     * the same last-name Soundex code (see {@link IdentityKeyUtils#soundex(String)}) and postcode. A
785	     * hard duplicate (identical identity key) has already been rejected with a 409 before this runs, so
786	     * this flags only the softer same-household-name overlap — in particular two owners with the same
787	     * last name and postcode but different telephones (whose identity keys therefore differ) are a soft
788	     * match rather than a rejected duplicate. The match with the lowest id is returned so the result is
789	     * deterministic when several owners qualify.
790	     *
791	     * @param owner the new owner being created, with its telephone already normalized
792	     * @return the matching existing owner, or {@code null} when none qualifies
793	     */
794	    private Owner findPossibleDuplicate(Owner owner) {
795	        if (owner.getLastName() == null || owner.getPostcode() == null) {
796	            return null;
797	        }
798	        String identityKey = ownerMapper.toIdentityKey(owner);
799	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
800	        return this.clinicService.findAllOwners().stream()
801	            .filter(existing -> !existing.isDeleted())
802	            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
803	            .filter(existing -> soundex.equals(IdentityKeyUtils.soundex(existing.getLastName())))
804	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
805	            .min(Comparator.comparingInt(Owner::getId))
806	            .orElse(null);
807	    }
808	
809	}
