import jakarta.servlet.http.HttpServletRequest;
import jakarta.transaction.Transactional;

/**
 * @author Vitaliy Fedoriv
 */

@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    /**
     * Dedicated logger for the welcome-notification queue. On a successful create a single line
     * carrying the new owner's id and member id is emitted here, standing in for enqueuing a
     * welcome notification to the owner.
     */
    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    /**
     * Assigns the monotonically increasing sequence number carried by each structured
     * {@link OwnerCreatedEvent}. Static so the order spans every create handled by this endpoint,
     * regardless of the controller instance, giving the audit event stream a total order.
     */
    private static final AtomicLong AUDIT_EVENT_SEQUENCE = new AtomicLong();

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    private final IdempotencyKeyRegistry idempotencyKeyRegistry;

    private final HttpServletRequest request;

    /** HTTP header carrying the idempotency key for the create-owner endpoint. */
    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper,
                                 IdempotencyKeyRegistry idempotencyKeyRegistry,
                                 HttpServletRequest request) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
        this.request = request;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        String idempotencyKey = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
        if (existingId != null) {
            Owner existing = this.clinicService.findOwnerById(existingId);
            if (existing != null) {
                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
            }
        }
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
        owner.setTelephone(normalizedTelephone);
        owner.setEmail(normalizeEmail(owner.getEmail()));
        applyAddress(owner);
        validatePostcode(owner.getCity(), owner.getPostcode());
        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
        if (effectiveRegistrationDate == null) {
            effectiveRegistrationDate = LocalDate.now();
        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                "registrationDate must not be later than the current server date");
        }
        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
        owner.setRegistrationDate(effectiveRegistrationDate);
        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
                "the maximum number of owners that may be created today has been reached");
        }
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        // The household id is deterministic (derived from the last name and postcode), so every
        // owner is keyed to its household automatically, regardless of creation order.
        this.clinicService.assignHousehold(owner);
        // An owner joining an existing household is now admitted rather than rejected; their
        // membership level is instead capped relative to the household (see the level-ceiling rule
        // applied via the membershipLevelCap below).
        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getHouseholdId(), null);
        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                "an owner with the same identity already exists");
        }
        int ownersInCity = countOwnersInCity(owner.getCity());
        if (ownersInCity >= CITY_CAPACITY) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                "city has reached its maximum number of owners");
        }
        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
        owner.setMemberId(memberIdFor(owner));
        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
        owner.setBulkSignupWarning(
            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
        // A declared household member (one created with 'sharesHousehold' that joins an existing
        // household) is not a suspected duplicate, so it is never flagged as a possible duplicate.
        boolean declaredHouseholdMember = sharesHousehold && householdInUse;
        Owner softDuplicate = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
        owner.setPossibleDuplicate(softDuplicate != null);
        owner.setPossibleDuplicateOf(softDuplicate == null ? null : softDuplicate.getId());
        this.clinicService.saveOwner(owner);
        this.idempotencyKeyRegistry.record(idempotencyKey, owner.getId());
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
            ownerDto.getMembershipLevel());
        OwnerCreatedEvent event = OwnerCreatedEvent.of(AUDIT_EVENT_SEQUENCE.incrementAndGet(),
            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
        AUDIT.info(event.toJson());
        NOTIFY.info("welcome queued: ownerId={} memberId={}", owner.getId(), owner.getMemberId());
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
        applyAddress(currentOwner);
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        this.clinicService.deleteOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Visit visit = visitMapper.toVisit(visitFieldsDto);
        Pet pet = new Pet();
        pet.setId(petId);
        visit.setPet(pet);
        this.clinicService.saveVisit(visit);
        VisitDto visitDto = visitMapper.toVisitDto(visit);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
            .buildAndExpand(visit.getId()).toUri());
        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
    }


    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner != null) {
            Pet pet = owner.getPet(petId);
            if (pet != null) {
                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

    /**
     * The owner's current primary identifier, carried by the structured {@link OwnerCreatedEvent}.
     * An owner's primary identifier is its {@code memberId}; this single accessor is the one place that
     * decides which field is primary, so the audit event always carries the member id.
     *
     * @param owner the created owner
     * @return the owner's current primary identifier
     */
    private String primaryIdentifier(Owner owner) {
        return owner.getMemberId();
    }

    /**
     * Builds the member id for a new owner, formatted {@code '<REGION><FY><HASH8><CHK>'} where REGION is
     * the version-2 region code — the region derived from the owner's postcode (preferring the postcode,
     * falling back to the city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)})
     * with the fixed {@link OwnerMapper#IDENTITY_VERSION_TAG 'V2' version tag} appended, FY is the
     * two-digit fiscal
     * year (starting 1 July; see {@link OwnerMapper#fiscalYear(LocalDate)}) of the business-day-adjusted
     * registration date, HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of the
     * owner's normalized E.164 telephone concatenated with the last name, and CHK is a single Luhn check
     * digit computed over the digits of {@code '<REGION><FY><HASH8>'} (see
     * {@link IdentityKeyUtils#luhnCheckDigit(String)}), e.g. {@code 'NSWV2271A2B3C4D5'}. The id carries no
     * sequence number, so its base form is a stable function of the owner's region, fiscal year and
     * telephone/last-name identity rather than of creation order.
     *
     * <p>When that computed id already belongs to an existing owner it is de-duplicated by appending
     * {@code '-<n>'} with the smallest {@code n} of 2 or more that yields an id no existing owner
     * already has; the de-duplicated id is returned.
     *
     * @param owner the owner being created, with its telephone already normalized to E.164 form and its
     *              registration date already business-day-adjusted
     * @return the assigned, collision-free member id
     */
    private String memberIdFor(Owner owner) {
        // Version-2 region code: the plain region with the fixed 'V2' version tag mixed in, so the member
        // id (and every value derived from it) changes and no version-1 member id is produced again. The
        // user-facing locality keeps the plain, untagged region (see OwnerMapper.toLocality).
        String region = ownerMapper.regionOf(owner) + IdentityKeyUtils.IDENTITY_VERSION_TAG;
        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
        String hash8 = IdentityKeyUtils.sha256UpperHex(owner.getTelephone() + owner.getLastName())
            .substring(0, 8);
        String base = region + fy + hash8;
        String memberId = base + IdentityKeyUtils.luhnCheckDigit(base);
        if (!isMemberIdInUse(memberId)) {
            return memberId;
        }
        int n = 2;
        String candidate = memberId + "-" + n;
        while (isMemberIdInUse(candidate)) {
            n++;
            candidate = memberId + "-" + n;
        }
        return candidate;
    }

    /**
     * Determines whether any existing owner already carries the given {@code memberId}, compared
     * exactly. Called while assigning a new owner's member id so collisions can be de-duplicated.
     *
     * @param memberId the candidate member id to look for
     * @return {@code true} if an existing owner already has that member id
     */
    private boolean isMemberIdInUse(String memberId) {
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (memberId.equals(existing.getMemberId())) {
                return true;
            }
        }
        return false;
    }

    /**
     * The maximum number of owners allowed to live in a single city. A create is rejected once the
     * owner's city already contains this many owners.
     */
    private static final int CITY_CAPACITY = 50;

    /**
     * The number of owners a city must already contain before a new owner in it is flagged with
     * {@code capacityWarning}. Once the city holds this many owners (but fewer than
     * {@link #CITY_CAPACITY}), the create still succeeds but is flagged as approaching the capacity
     * limit.
     */
    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;

    /**
     * The maximum number of owners that may be created on a single day. A create is rejected with
     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
     * {@code registrationDate}.
     */
    private static final int DAILY_CREATE_LIMIT = 100;

    /**
     * The number of owners that must already have been created for the current day before a new
     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
     * owners already carry today's {@code registrationDate}.
     */
    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;

    /**
     * The fixed public holidays that the business-day roll skips. A registration date landing on one
     * of these dates is rolled forward, exactly as it is for a weekend day.
     */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
        LocalDate.parse("2026-01-01"),
        LocalDate.parse("2026-01-26"),
        LocalDate.parse("2026-04-25"),
        LocalDate.parse("2026-12-25"),
        LocalDate.parse("2026-12-28"));

    /**
     * Rolls a registration date forward onto a business day: a date that falls on a Saturday, a
     * Sunday or a listed public holiday is advanced one day at a time until it lands on a weekday
     * that is not a public holiday, while a date already on a non-holiday weekday is returned
     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
     * date) so that the stored {@code registrationDate}, and every value derived from it, always
     * falls on a business day.
     *
     * @param date the effective registration date
     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
     */
    private static LocalDate rollToBusinessDay(LocalDate date) {
        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private static boolean isWeekend(LocalDate date) {
        return switch (date.getDayOfWeek()) {
            case SATURDAY, SUNDAY -> true;
            default -> false;
        };
    }

    /**
     * Counts the existing owners whose {@code registrationDate} equals the given (already
     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
     * business day. Called before a new owner is saved, so the returned value reflects the number of
     * owners created for that day prior to this create.
     *
     * @param date the adjusted business-day registration date to count against
     * @return the number of existing owners registered on that date
     */
    private int countOwnersRegisteredOn(LocalDate date) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> date.equals(existing.getRegistrationDate()))
            .count();
    }

    /**
     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
     *
     * @param city the city to count owners for
     * @return the number of existing owners in that city
     */
    private int countOwnersInCity(String city) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
            .count();
    }

    /**
     * Counts the existing owners that already share the given first name and last name, comparing
     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
     * the number of namesakes that existed prior to this create.
     *
     * @param firstName the new owner's first name
     * @param lastName  the new owner's last name
     * @return the number of existing owners with the same first and last name
     */
    private int countNamesakes(String firstName, String lastName) {
        int count = 0;
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (firstName.equalsIgnoreCase(existing.getFirstName())
                && lastName.equalsIgnoreCase(existing.getLastName())) {
                count++;
            }
        }
        return count;
    }

    /**
     * Counts the existing owners that already belong to the given household (i.e. that share the
     * given {@code householdId}). Called before a new owner is saved, so adding one for the owner
     * being created yields the household's total size at the moment of creation. Owners without a
     * household id are ignored.
     *
     * @param householdId the new owner's assigned household id
     * @return the number of existing owners already in that household
     */
    private int countHouseholdMembers(String householdId) {
        if (householdId == null) {
            return 0;
        }
        int count = 0;
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (householdId.equals(existing.getHouseholdId())) {
                count++;
            }
        }
        return count;
    }

    /**
     * Computes the membership-level ceiling for a new owner joining the given household: one above the
     * current maximum effective membership level among the existing owners in that household. The
     * ceiling is frozen on the owner at creation and later applied by
     * {@link OwnerMapper#toMembershipLevel(Owner)}. Returns {@code null} when the household has no
     * existing member (or the owner has no household id), meaning no cap applies.
     *
     * @param householdId the new owner's assigned household id
     * @return one above the household's current maximum membership level, or {@code null} when the
     *         household has no existing member
     */
    private Integer householdMembershipLevelCap(String householdId) {
        if (householdId == null) {
            return null;
        }
        Integer maxLevel = null;
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (householdId.equals(existing.getHouseholdId())) {
                int level = ownerMapper.toMembershipLevel(existing);
                if (maxLevel == null || level > maxLevel) {
                    maxLevel = level;
                }
            }
        }
        return maxLevel == null ? null : maxLevel + 1;
    }

    /**
     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
     * string is what gets stored and returned.
     *
     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
     *
     * <p>Once in E.164 form the national-number length is validated against the country code: a
     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
     * number exactly 10 (see {@link E164PhoneNumbers#NATIONAL_LENGTHS}). Country codes without a configured
     * rule are accepted on the general 8-to-15 digit length alone.
     *
     * @param telephone the raw telephone value supplied by the client
     * @return the normalized E.164 telephone number
     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
     *                                 after the {@code '+'}, or the wrong national-number length for
     *                                 its country code)
     */
    private static String normalizeTelephone(String telephone) {
        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        } else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("[0-9]{8,15}")) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                "telephone could not be normalized to a valid E.164 number");
        }
        validateNationalNumberLength(digits);
        return "+" + digits;
    }

    /**
     * Validates the national-number length of an E.164 number (its digits, without the leading
     * {@code '+'}) against its country code. The longest dialling code that prefixes the number (see
     * {@link E164PhoneNumbers#countryCode}) selects the rule; if none is configured the number passes
     * (only the general 8-to-15 digit rule applies).
     *
     * @param digits the E.164 digits without the leading {@code '+'}
     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
     *                                 digits does not match the country code's required length
     */
    private static void validateNationalNumberLength(String digits) {
        E164PhoneNumbers.countryCode(digits)
            .ifPresent(code -> {
                int nationalLength = digits.length() - code.length();
                int required = E164PhoneNumbers.NATIONAL_LENGTHS.get(code);
                if (nationalLength != required) {
                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                        "telephone must have " + required
                            + " national digits for country code +" + code);
                }
            });
    }

    /**
     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
     * containing at least one dot, none of the three sections containing whitespace or an
     * additional {@code @}.
     */
    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    /**
     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
     * (email is optional). When a value is supplied it must be a syntactically valid address whose
     * domain is not on the disposable-domain blocklist; the value is then stored and returned
     * lower-cased.
     *
     * @param email the raw email value supplied by the client, possibly {@code null}
     * @return the lower-cased email, or {@code null} when none was supplied
     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
     *                                 is not a syntactically valid address, or its domain is on the
     *                                 disposable-domain blocklist
     */
    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }
        if (!EMAIL_PATTERN.matcher(email).matches()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                "email must be a syntactically valid address");
        }
        String normalized = email.toLowerCase(Locale.ROOT);
        String domain = normalized.substring(normalized.indexOf('@') + 1);
        if (DisposableEmailDomains.BLOCKLIST.contains(domain)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                "email domain " + domain + " is not allowed");
        }
        return normalized;
    }

    /**
     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
     */
    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /**
     * Validates an owner's optional postcode against the city's region. Postcode is validated only
     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
     * four-digit format is enforced by request validation; here the value is range-checked: when the
     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
     * accepts any four-digit postcode.
     *
     * @param city     the owner's city
     * @param postcode the owner's postcode, possibly {@code null}
     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
     *                                 out of range for the city's region
     */
    private static void validatePostcode(String city, String postcode) {
        if (postcode == null) {
            return;
        }
        String region = OwnerMapper.CITY_REGION.get(city);
        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
        if (range == null) {
            return;
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                "postcode " + postcode + " is not valid for region " + region);
        }
    }

    /**
     * Common street-type abbreviations expanded to their full word during address normalization.
     * Keys and values are upper-case; matching is done per whitespace-delimited token.
     */
    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    /**
     * Applies an owner's address, accepting either the structured form (a non-blank
     * {@code addressLine1} with an optional {@code addressLine2}) or the flat {@code address} form,
     * preferring the structured fields when present. Whichever fields are supplied are normalized
     * (see {@link #normalizeAddress(String)}), and the stored flat {@code address} is set to the
     * composed value: the normalized {@code addressLine1}, with a single space and the normalized
     * {@code addressLine2} appended when an {@code addressLine2} was supplied. When only the flat
     * form is supplied, the normalized flat address is stored and both structured lines are cleared.
     * This keeps the request contract backward-compatible: an owner that supplied just the flat
     * {@code address} (plus city) is still accepted.
     *
     * @param owner the owner being created or updated, carrying the raw address fields
     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if neither a non-blank
     *                                 {@code addressLine1} nor a non-blank flat {@code address} was
     *                                 supplied
     */
    private static void applyAddress(Owner owner) {
        boolean hasStructured = owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank();
        boolean hasFlat = owner.getAddress() != null && !owner.getAddress().isBlank();
        if (!hasStructured && !hasFlat) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                "an address must be supplied, either 'addressLine1' or 'address'");
        }
        if (hasStructured) {
            String line1 = normalizeAddress(owner.getAddressLine1());
            owner.setAddressLine1(line1);
            String composed = line1;
            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
                String line2 = normalizeAddress(owner.getAddressLine2());
                owner.setAddressLine2(line2);
                composed = line1 + " " + line2;
            } else {
                owner.setAddressLine2(null);
            }
            owner.setAddress(composed);
        } else {
            owner.setAddressLine1(null);
            owner.setAddressLine2(null);
            owner.setAddress(normalizeAddress(owner.getAddress()));
        }
    }

    /**
     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
     * {@code AVE -> AVENUE}). This normalized value is what gets stored and returned.
     *
     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
     *
     * @param address the raw address supplied by the client, possibly {@code null}
     * @return the normalized address
     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
     *                                 after normalization (required field)
     */
    private static String normalizeAddress(String address) {
        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
        if (collapsed.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                "address must not be blank");
        }
        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
        StringBuilder normalized = new StringBuilder();
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                normalized.append(' ');
            }
            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return normalized.toString();
    }

    /**
     * Determines whether the given whole identity key already belongs to any owner other than the
     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
     *
     * @param identityKey the identity key to look for
     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
     * @return {@code true} if another owner already has the same identity key
     */
    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
        for (Owner existing : this.clinicService.findAllOwners()) {
            if (existing.isDeleted()) {
                continue;
            }
            if (excludeId != null && excludeId.equals(existing.getId())) {
                continue;
            }
            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
                return true;
            }
        }
        return false;
    }

    /**
     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
     * (soft) duplicate of: one whose identity key <em>differs</em> from the new owner's while sharing
     * the same last-name Soundex code (see {@link IdentityKeyUtils#soundex(String)}) and postcode. A
     * hard duplicate (identical identity key) has already been rejected with a 409 before this runs, so
     * this flags only the softer same-household-name overlap — in particular two owners with the same
     * last name and postcode but different telephones (whose identity keys therefore differ) are a soft
     * match rather than a rejected duplicate. The match with the lowest id is returned so the result is
     * deterministic when several owners qualify.
     *
     * @param owner the new owner being created, with its telephone already normalized
     * @return the matching existing owner, or {@code null} when none qualifies
     */
    private Owner findPossibleDuplicate(Owner owner) {
        if (owner.getLastName() == null || owner.getPostcode() == null) {
            return null;
        }
        String identityKey = ownerMapper.toIdentityKey(owner);
        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .filter(existing -> !identityKey.equals(ownerMapper.toIdentityKey(existing)))
            .filter(existing -> soundex.equals(IdentityKeyUtils.soundex(existing.getLastName())))
            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
            .min(Comparator.comparingInt(Owner::getId))
            .orElse(null);
    }

}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerIdentityDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.util.DisposableEmailDomains;
import org.springframework.samples.petclinic.util.E164PhoneNumbers;
import org.springframework.samples.petclinic.util.IdentityKeyUtils;

import java.time.LocalDate;
import java.time.Month;
import java.time.Period;
import java.util.Collection;
import java.util.List;
import java.util.Map;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials",
        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
    @Mapping(target = "membershipPoints",
        expression = "java(toMembershipPoints(owner))")
    @Mapping(target = "membershipLevel",
        expression = "java(toMembershipLevel(owner))")
    @Mapping(target = "locality",
        expression = "java(toLocality(owner))")
    @Mapping(target = "ownerSegment",
        expression = "java(toOwnerSegment(owner))")
    @Mapping(target = "timezone",
        expression = "java(toTimezone(owner))")
    @Mapping(target = "contactPreference",
        expression = "java(toContactPreference(owner))")
    @Mapping(target = "apiVersion",
        expression = "java(IDENTITY_API_VERSION)")
    @Mapping(target = "identity",
        expression = "java(toIdentity(owner))")
    @Mapping(target = "ageBand",
        expression = "java(toAgeBand(owner))")
    @Mapping(target = "telephoneDisplay",
        expression = "java(toTelephoneDisplay(owner))")
    @Mapping(target = "salutation",
        expression = "java(toSalutation(owner))")
    @Mapping(target = "fiscalYear",
        expression = "java(toFiscalYear(owner))")
    @Mapping(target = "selfLink",
        expression = "java(toSelfLink(owner))")
    @Mapping(target = "riskFlag",
        expression = "java(toRiskFlag(owner))")
    OwnerDto toOwnerDto(Owner owner);

    /**
     * Derive an owner's risk flag: {@code true} when the owner warrants a manual risk review, defined
     * as the logical OR of three conditions — the owner is a possible duplicate
     * ({@code possibleDuplicate} is true), the owner's email domain is disposable-adjacent (see
     * {@link #hasDisposableAdjacentEmail(Owner)}), or the owner's city is over its soft capacity
     * ({@code capacityWarning} is true). Otherwise {@code false}. Derived at read time.
     */
    default Boolean toRiskFlag(Owner owner) {
        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
            || Boolean.TRUE.equals(owner.getCapacityWarning())
            || hasDisposableAdjacentEmail(owner);
    }

    /**
     * Whether the owner's email domain is disposable-adjacent: a domain that is not itself a
     * whole-blocklisted disposable domain (those are rejected at creation) but shares a known
     * disposable provider's second-level label — i.e. one of the domain's dot-separated labels equals a
     * label in {@link DisposableEmailDomains#BASE_LABELS}. This catches subdomains of a disposable provider
     * (e.g. {@code sub.mailinator.com}) and the same base under a different TLD (e.g.
     * {@code mailinator.net}), while a merely similar label (e.g. {@code mymailinator.com}) is not
     * matched. Returns {@code false} when the owner has no email or the value carries no domain.
     */
    default boolean hasDisposableAdjacentEmail(Owner owner) {
        if (!hasEmail(owner)) {
            return false;
        }
        String email = owner.getEmail();
        int at = email.lastIndexOf('@');
        if (at < 0 || at == email.length() - 1) {
            return false;
        }
        String domain = email.substring(at + 1).toLowerCase();
        for (String label : domain.split("\\.")) {
            if (DisposableEmailDomains.BASE_LABELS.contains(label)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Derive an owner's canonical self link: the resource path {@code '/api/owners/<id>'} where
     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet (the field is
     * then absent from the DTO).
     */
    default String toSelfLink(Owner owner) {
        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
    }

    /**
     * The fiscal year that the given date falls in, where the fiscal year starts on 1 July and is
     * identified by the calendar year in which it ends. A date on or after 1 July belongs to the
     * fiscal year ending in the following calendar year (e.g. 2026-08-01 -&gt; 2027), while a date
     * before 1 July belongs to the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt;
     * 2026). This is the single source of truth for the fiscal year used both when the create endpoint
     * bakes the FY segment into the member id (see {@code OwnerRestControllerV1.memberIdFor}) and when
     * the DTO's {@code fiscalYear} falls back to the registration date for a legacy record.
     *
     * @param date the date to resolve, on a business day
     * @return the calendar year in which that date's fiscal year ends
     */
    static int fiscalYear(LocalDate date) {
        int year = date.getYear();
        return date.getMonthValue() >= Month.JULY.getValue() ? year + 1 : year;
    }

    /**
     * Derive an owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the two-digit fiscal-year
     * segment carried by the {@code memberId} (see {@link #memberIdBase(String)}), e.g. {@code 'FY27'}.
     * The fiscal year therefore moves with the owner's member id. When an owner has no (well-formed)
     * member id yet (e.g. legacy records) it falls back to deriving the fiscal year directly from the
     * business-day-adjusted {@code registrationDate} (see {@link #fiscalYear(LocalDate)}), and returns
     * {@code null} when neither is present (the field is then absent from the DTO).
     */
    default String toFiscalYear(Owner owner) {
        String base = memberIdBase(owner.getMemberId());
        if (base != null) {
            return "FY" + memberIdFyDigits(base);
        }
        LocalDate registrationDate = owner.getRegistrationDate();
        return registrationDate == null ? null : String.format("FY%02d", fiscalYear(registrationDate) % 100);
    }

    /**
     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
     * just the last name.
     */
    default String toSalutation(Owner owner) {
        String lastName = owner.getLastName();
        String title = owner.getTitle();
        if (title == null || title.isBlank()) {
            return lastName;
        }
        return title + " " + lastName;
    }

    /**
     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
     * registration date is missing (e.g. legacy records) the current date is used as the reference.
     */
    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
        LocalDate birthDate = owner.getBirthDate();
        if (birthDate == null) {
            return null;
        }
        LocalDate reference = owner.getRegistrationDate() != null
            ? owner.getRegistrationDate() : LocalDate.now();
        int age = Period.between(birthDate, reference).getYears();
        if (age < 18) {
            return OwnerDto.AgeBandEnum.MINOR;
        }
        if (age < 65) {
            return OwnerDto.AgeBandEnum.ADULT;
        }
        return OwnerDto.AgeBandEnum.SENIOR;
    }

    /**
     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
     *
     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
     * code, a two-digit country code is assumed (the most common length).
     */
    default String toTelephoneDisplay(Owner owner) {
        String telephone = owner.getTelephone();
        if (telephone == null || !telephone.startsWith("+")) {
            return telephone;
        }
        String digits = telephone.substring(1);
        String code = E164PhoneNumbers.countryCode(digits)
            .filter(c -> digits.length() > c.length())
            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
        String national = digits.substring(code.length());
        StringBuilder sb = new StringBuilder("+").append(code);
        for (int i = 0; i < national.length(); i += 3) {
            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
        }
        return sb.toString();
    }

    /**
     * The fixed trailing-segment widths of a member id base {@code '<REGION><FY><HASH8><CHK>'}: FY is 2
     * digits, HASH8 is 8 hex characters and CHK is 1 digit, so the last {@link #MEMBER_ID_SUFFIX_WIDTH}
     * characters are the {@code <FY><HASH8><CHK>} suffix and REGION is the variable-width remainder in
     * front of it. This is the single place the layout is encoded; the position arithmetic in
     * {@link #memberIdRegion(String)} and {@link #memberIdFyDigits(String)} derives from these, and it
     * must stay in step with how {@code OwnerRestControllerV1.memberIdFor} assembles the id.
     */
    int FY_WIDTH = 2;
    int HASH8_WIDTH = 8;
    int CHK_WIDTH = 1;
    int MEMBER_ID_SUFFIX_WIDTH = FY_WIDTH + HASH8_WIDTH + CHK_WIDTH;

    /**
     * The {@code '<REGION><FY><HASH8><CHK>'} base of a member id, dropping any {@code '-<n>'} collision
     * suffix, or {@code null} when the owner has no (well-formed) member id yet — i.e. one long enough to
     * carry a non-empty REGION in front of the fixed {@link #MEMBER_ID_SUFFIX_WIDTH}-character suffix.
     * Use {@link #memberIdRegion(String)} and {@link #memberIdFyDigits(String)} to decode its segments.
     */
    private static String memberIdBase(String memberId) {
        if (memberId == null) {
            return null;
        }
        int dash = memberId.indexOf('-');
        String base = dash >= 0 ? memberId.substring(0, dash) : memberId;
        return base.length() > MEMBER_ID_SUFFIX_WIDTH ? base : null;
    }

    /**
     * The leading {@code <REGION>} segment of a (non-null, well-formed) member id base: everything
     * before the fixed trailing {@code <FY><HASH8><CHK>} suffix.
     */
    private static String memberIdRegion(String base) {
        return base.substring(0, base.length() - MEMBER_ID_SUFFIX_WIDTH);
    }

    /**
     * The two-digit {@code <FY>} segment of a (non-null, well-formed) member id base: the characters
     * immediately preceding the trailing HASH8 and CHK segments.
     */
    private static String memberIdFyDigits(String base) {
        int fyEnd = base.length() - HASH8_WIDTH - CHK_WIDTH;
        return base.substring(fyEnd - FY_WIDTH, fyEnd);
    }

    /**
     * The identity API version carried by the owner response. Version 2 groups the identifiers under the
     * nested {@code identity} object and derives them with the version-2 algorithm (see
     * {@link IdentityKeyUtils#IDENTITY_VERSION_TAG}).
     */
    int IDENTITY_API_VERSION = 2;

    /**
     * Groups the owner's version-2 identifiers — the member id, household id and identity key — under the
     * nested {@code identity} object of the DTO. Each identifier is derived by the version-2 algorithm
     * (see {@link #IDENTITY_VERSION_TAG}); the identity key is (re)derived here from the same single
     * source of truth used by the create endpoint's duplicate check, while the member id and household id
     * are the values frozen on the owner at creation.
     */
    default OwnerIdentityDto toIdentity(Owner owner) {
        OwnerIdentityDto identity = new OwnerIdentityDto();
        identity.setMemberId(owner.getMemberId());
        identity.setHouseholdId(owner.getHouseholdId());
        identity.setIdentityKey(toIdentityKey(owner));
        return identity;
    }

    /**
     * Derive an owner's version-2 duplicate-detection identity key: the lower-case SHA-256 hex digest
     * (64 characters) of the normalized E.164 telephone, the lower-cased email (empty when none), the
     * American Soundex code of the last name and the fixed {@link #IDENTITY_VERSION_TAG version tag},
     * joined with {@code '|'}. Mixing in the version tag means no key produced under version 1 is
     * produced again. Two owners are duplicates only when their whole identity keys are equal.
     *
     * <p>This is the single source of truth for the key: it is both returned on the DTO (under
     * {@code identity}) and used by the create endpoint's 409 duplicate check, so the value clients see
     * is exactly the value that governs rejection. The "email present" rule reuses
     * {@link #hasEmail(Owner)}, and the Soundex and hashing come from {@link IdentityKeyUtils}, the same
     * helpers the soft-match uses.
     */
    default String toIdentityKey(Owner owner) {
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        String email = hasEmail(owner) ? owner.getEmail() : "";
        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
        return IdentityKeyUtils.sha256Hex(
            telephone + "|" + email + "|" + soundex + "|" + IDENTITY_VERSION_TAG);
    }

    /**
     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
     * for the "is an email present" rule shared by the derived fields below.
     */
    default boolean hasEmail(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isEmpty();
    }

    /**
     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
     * otherwise 'PHONE'.
     */
    default String toContactPreference(Owner owner) {
        return hasEmail(owner) ? "EMAIL" : "PHONE";
    }

    /**
     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
     * and no namesakes in a single-member household scores 3 points.
     */
    default Integer toMembershipPoints(Owner owner) {
        int points = 0;
        if (hasEmail(owner)) {
            points += 2;
        }
        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
        if (noNamesakes) {
            points += 1;
        }
        if (hasHouseholdBonus(owner)) {
            points += 2;
        }
        if (hasTenureBonus(owner)) {
            points += 3;
        }
        return points;
    }

    /**
     * Whether the owner belongs to a household of 3 or more members. The household size is the count
     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
     * Returns {@code false} when no household size is present (e.g. legacy records).
     */
    default boolean hasHouseholdBonus(Owner owner) {
        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
    }

    /**
     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
     * or more.
     *
     * <p>The level is then capped at the owner's {@code membershipLevelCap} when one is present: a new
     * owner's membership level cannot exceed one above the current maximum membership level among their
     * existing household members, so the cap (frozen at creation, see the create endpoint) is the
     * ceiling applied here. When no cap is present (e.g. an owner created with no existing household
     * member, or a legacy record) the uncapped level stands.
     */
    default Integer toMembershipLevel(Owner owner) {
        int level = uncappedMembershipLevel(owner);
        Integer cap = owner.getMembershipLevelCap();
        if (cap != null && level > cap) {
            return cap;
        }
        return level;
    }

    /**
     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
     * {@link #toMembershipPoints(Owner)}) before any household ceiling is applied: level 1 for 0-1
     * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
     */
    default Integer uncappedMembershipLevel(Owner owner) {
        int points = toMembershipPoints(owner);
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    /**
     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
     * no registration date is present.
     */
    default boolean hasTenureBonus(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return false;
        }
        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
    }

    /**
     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
     */
    Map<String, String> CITY_REGION = Map.of(
        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /**
     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
     * inclusive.
     */
    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /**
     * Derive an owner's locality: the plain, unversioned region code, derived directly from the postcode
     * (falling back to the fixed city-to-region table, else {@code 'UNKNOWN'}; see
     * {@link #regionOf(Owner)}). The locality is a user-facing field, not an identifier, so it must stay
     * the plain region code (e.g. {@code 'NSW'}) and must never carry the {@link #IDENTITY_VERSION_TAG}
     * that the version-2 algorithm mixes into the region code <em>inside</em> the member id. It is
     * therefore recomputed from the owner rather than read back out of the (now version-2-tagged)
     * member id.
     */
    default String toLocality(Owner owner) {
        return regionOf(owner);
    }

    /**
     * Derive an owner's marketing segment, formatted {@code '<TIER>_<AREA>'} and one of
     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when the owner's membership level (see
     * {@link #toMembershipLevel(Owner)}) is 3 or more, otherwise {@code 'STANDARD'}. AREA is
     * {@code 'METRO'} when the owner's locality (see {@link #toLocality(Owner)}) is a known region
     * (NSW, VIC or QLD, i.e. one carrying a {@link #REGION_TIMEZONE} entry), otherwise
     * {@code 'REGIONAL'}.
     */
    default String toOwnerSegment(Owner owner) {
        String tier = toMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
        String area = REGION_TIMEZONE.containsKey(toLocality(owner)) ? "METRO" : "REGIONAL";
        return tier + "_" + area;
    }

    /**
     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
     */
    Map<String, String> REGION_TIMEZONE = Map.of(
        "NSW", "Australia/Sydney",
        "VIC", "Australia/Melbourne",
        "QLD", "Australia/Brisbane");

    /**
     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
     */
    default String toTimezone(Owner owner) {
        return REGION_TIMEZONE.get(toLocality(owner));
    }

    /**
     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This plain region code is both
     * the owner's user-facing {@link #toLocality(Owner) locality} and, with the
     * {@link #IDENTITY_VERSION_TAG 'V2' version tag} mixed in, the region code baked into the leading
     * {@code <REGION>} segment of a new owner's member id.
     */
    default String regionOf(Owner owner) {
        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
        // type conversion and wrongly apply it to other String properties (e.g. telephone).
        String postcode = owner.getPostcode();
        if (postcode != null) {
            try {
                int value = Integer.parseInt(postcode.trim());
                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
                    int[] range = entry.getValue();
                    if (value >= range[0] && value <= range[1]) {
                        return entry.getKey();
                    }
                }
            }
            catch (NumberFormatException ignored) {
                // Non-numeric postcode: fall back to the city table below.
            }
        }
        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

